mapper.update:
update
    sys_industry_auth old,
    sys_industry_auth new,
    sys_role_industry_auth a
set a.auth_id = new.auth_id
where old.industry_code = #{sourceIndustryCode} and old.app_ver_code = #{sourceAppVerCode}
    and new.industry_code = #{targetIndustryCode} and new.app_ver_code = #{targetAppVerCode}
    and a.tenant_id = #{tenantId} and old.menu_id is not null and old.menu_id != ""
    and old.menu_id = new.menu_id and old.auth_id is not null and old.auth_id != ""
    and a.auth_id = old.auth_id;

mapper.delete:
delete from sys_role_industry_auth where tenant_id = #{tenantId} and auth_id in (
    select auth_id from sys_industry_auth
    where industry_code = #{sourceIndustryCode} and app_ver_code = #{sourceAppVerCode}
);

mapper.select:
select creator
from resource_type
where tenant_id = #{tenantId} and delete_flag = 0 and industry_code = #{sourceIndustryCode}
and app_ver_code = #{sourceAppVerCode} limit 1;

mapper.update:
update resource_type set delete_flag = 1
where tenant_id = #{tenantId} and delete_flag = 0
and industry_code = #{sourceIndustryCode} and app_ver_code = #{sourceAppVerCode};

