mapper.update:
update vm_order_package
set industry_code = #{targetIndustryCode}, app_ver_code = #{targetAppVerCode}

    , app_ver_name = #{targetIndustryName}

where tenant_id = #{tenantId} and accept_node = #{acceptNode} and industry_code = #{sourceIndustryCode} and app_ver_code = #{sourceAppVerCode};

update vm_order_package_his
set industry_code = #{targetIndustryCode}, app_ver_code = #{targetAppVerCode}

    , app_ver_name = #{targetIndustryName}

where tenant_id = #{tenantId} and accept_node = #{acceptNode} and industry_code = #{sourceIndustryCode} and app_ver_code = #{sourceAppVerCode};

mapper.select:
select a.AREA_CODE areaCode, concat(a2.AREA_NAME,a1.AREA_NAME,a.AREA_NAME) areaName, a.LONGITUDE longitude, a.LATITUDE latitude from sys_dept_street_rel t left join sys_area a on t.county_code = a.AREA_CODE left join sys_area a1 on a.AREA_PARENT_CODE = a1.AREA_CODE left join sys_area a2 on a1.AREA_PARENT_CODE = a2.AREA_CODE where t.tenant_id = #{dto.tenantId}
and t.industry_code = #{dto.industryCode}
and a.AREA_CODE = #{dto.adCode}
group by a.AREA_CODE
